#!/bin/sh
# Compare the speed of code generated by mcc with clang -O2.
#
#   sh bench/cmp.sh [runs] [mcc]        (defaults: 5 runs, build/stage0/mcc)
#
# Part 1 builds bench/bench.c three ways (mcc, mcc -O3, clang -O2), checks that all print the same
# checksums, runs each `runs` times in turn and prints, per kernel, the least time of each build and
# the ratios mcc/clang. Part 2 is the self-compile workload: mcc's own source is built into a compiler by
# mcc and by clang -O2, and each of those compilers then compiles the source tree (one process, objects
# only); the least cycle count of `runs` runs is compared. A ratio above 1 means mcc's code is slower.
# Everything is written under build/test/cmp. BENCH_ONLY=1 skips part 2.
runs=${1:-5}
mcc=${2:-build/stage0/mcc}
dir=build/test/cmp
mkdir -p $dir || exit 1
home=$(cd "$(dirname "$mcc")" && pwd)

$mcc bench/bench.c -o $dir/b_mcc || exit 1
$mcc -O3 bench/bench.c -o $dir/b_mcc3 || exit 1
clang -O2 -w bench/bench.c -o $dir/b_clang || exit 1
for v in mcc mcc3 clang; do
    : > $dir/t_$v
done
i=0
while [ $i -lt $runs ]; do
    for v in mcc mcc3 clang; do
        $dir/b_$v > $dir/o_$v 2>> $dir/t_$v || { echo "cmp: b_$v failed"; exit 1; }
    done
    i=$((i + 1))
done
cmp -s $dir/o_mcc $dir/o_clang && cmp -s $dir/o_mcc3 $dir/o_clang || { echo "cmp: checksums differ"; exit 1; }
echo "kernel        mcc    mcc-O3     clang   mcc/clang  O3/clang   (ms, least of $runs)"
for v in mcc mcc3 clang; do
    awk -v v=$v '{ if (!($1 in m) || $2 < m[$1]) m[$1] = $2; if (!($1 in o)) { o[$1] = n++; k[n - 1] = $1 } }
        END { for (i = 0; i < n; i++) print k[i], m[k[i]] }' $dir/t_$v > $dir/min_$v
done
paste -d ' ' $dir/min_mcc $dir/min_mcc3 $dir/min_clang | awk '
    { printf "%-9s %8.2f %9.2f %9.2f %9.2f %9.2f\n", $1, $2, $4, $6, $2 / $6, $4 / $6
      lm += log($2 / $6); l3 += log($4 / $6); n++ }
    END { printf "%-9s %28s %9.2f %9.2f\n", "geomean", "", exp(lm / n), exp(l3 / n) }'
[ -n "$BENCH_ONLY" ] && exit 0

# Self-compile: the same source built into two compilers, each timed compiling that source.
$mcc -o $dir/sc_mcc src/*.c || exit 1
clang -O2 -w -o $dir/sc_clang src/*.c || exit 1
src=$(pwd)/src
for v in mcc clang; do
    mkdir -p $dir/out_$v
    : > $dir/c_$v
done
i=0
while [ $i -lt $runs ]; do
    for v in mcc clang; do
        (cd $dir/out_$v && MCC_HOME=$home /usr/bin/time -l ../sc_$v -j1 -c $src/*.c 2>&1 |
            awk '/cycles elapsed/ { c = $1 } /instructions retired/ { n = $1 } END { print c, n }') >> $dir/c_$v
    done
    i=$((i + 1))
done
cmp -s $dir/out_mcc/parse.o $dir/out_clang/parse.o || { echo "cmp: the two compilers disagree"; exit 1; }
for v in mcc clang; do
    sort -n $dir/c_$v | head -1 > $dir/cmin_$v
done
paste -d ' ' $dir/cmin_mcc $dir/cmin_clang | awk '
    { printf "selfcomp  %8.0f %9s %9.0f %9.3f   (M cycles, least of '$runs'; instructions %.0fM vs %.0fM, %.3f)\n",
        $1 / 1e6, "", $3 / 1e6, $1 / $3, $2 / 1e6, $4 / 1e6, $2 / $4 }'
